package dev.forgebridge.tests;

import dev.forgebridge.api.placeholder.PlaceholderClassGenerator;
import dev.forgebridge.api.placeholder.PlaceholderLibrary;
import dev.forgebridge.remap.BuiltinMappings;
import dev.forgebridge.remap.MappingTable;

import org.objectweb.asm.ClassReader;

import java.io.File;
import java.io.FileOutputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.List;
import java.util.Map;

/**
 * The placeholder classes are generated bytecode, so they are verified by loading them.
 * A stub that only looks right in a hex dump is worthless: the mod calls it.
 */
public final class PlaceholderTests {

    private PlaceholderTests() {
    }

    public static void testDefaultLibraryCoversTheRemovedApis() {
        PlaceholderLibrary library = PlaceholderLibrary.defaultLibrary();
        Assert.equalInt(8, library.size(), "placeholder count");
        PlaceholderLibrary.Placeholder modLoading = library.get("net/minecraftforge/fml/ModLoadingContext");
        Assert.notNull(modLoading, "ModLoadingContext placeholder");
        Assert.equal("dev/forgebridge/placeholders/fml/ModLoadingContext",
                modLoading.getStubName(), "stub name mirrors the legacy name without its prefix");
        Assert.contains(modLoading.getMessage(), "ModContainer", "message points at the replacement");
        PlaceholderLibrary.Placeholder capability =
                library.get("net/minecraftforge/common/capabilities/ICapabilityProvider");
        Assert.notNull(capability, "ICapabilityProvider placeholder");
    }

    public static void testEveryGeneratedClassParsesAsBytecode() {
        PlaceholderLibrary library = PlaceholderLibrary.defaultLibrary();
        Map<String, byte[]> entries = library.asClassEntries();
        Assert.equalInt(library.size() + 1, entries.size(), "one entry per placeholder plus the support class");
        for (Object element : entries.entrySet()) {
            Map.Entry entry = (Map.Entry) element;
            String name = String.valueOf(entry.getKey());
            byte[] bytes = (byte[]) entry.getValue();
            Assert.isTrue(bytes.length > 32, name + " has content");
            ClassReader reader = new ClassReader(bytes);
            Assert.notNull(reader.getClassName(), name + " readable by ASM");
            // Class file 65 = Java 21, the level NeoForge 21.1 runs on.
            Assert.equalInt(65, reader.readUnsignedShort(6), name + " targets Java 21");
        }
    }

    public static void testStubClassesLoadAndExplainThemselves() throws Exception {
        File dir = Fixtures.tempDir("forgebridge-placeholders");
        URLClassLoader loader = null;
        try {
            PlaceholderLibrary library = PlaceholderLibrary.defaultLibrary();
            Map<String, byte[]> entries = library.asClassEntries();
            for (Object element : entries.entrySet()) {
                Map.Entry entry = (Map.Entry) element;
                File target = new File(dir, String.valueOf(entry.getKey()));
                target.getParentFile().mkdirs();
                FileOutputStream out = new FileOutputStream(target);
                try {
                    out.write((byte[]) entry.getValue());
                } finally {
                    out.close();
                }
            }
            loader = new URLClassLoader(new URL[]{dir.toURI().toURL()},
                    PlaceholderTests.class.getClassLoader());

            Class<?> stub = Class.forName("dev.forgebridge.placeholders.fml.ModLoadingContext", true, loader);
            Assert.isTrue(stub.getField(PlaceholderClassGenerator.MARKER_FIELD)
                    .getBoolean((Object) null), "marker field is set so the stub can be recognised at runtime");

            Method get = stub.getMethod("get", new Class<?>[0]);
            Object instance = get.invoke(null, new Object[0]);
            Assert.notNull(instance, "static get() returns a usable stub instance");
            String text = String.valueOf(instance);
            Assert.contains(text, "ForgeBridge placeholder", "toString explains what happened");
            Assert.contains(text, "ModContainer", "toString names the replacement");

            Class<?> capability = Class.forName(
                    "dev.forgebridge.placeholders.common.capabilities.ICapabilityProvider", true, loader);
            Assert.isTrue(capability.isInterface(), "ICapabilityProvider placeholder stays an interface");
            Field message = capability.getField(PlaceholderClassGenerator.MESSAGE_FIELD);
            Assert.contains(String.valueOf(message.get((Object) null)), "CapabilityToken", "interface message");
        } finally {
            if (loader != null) {
                loader.close();
            }
            Fixtures.deleteTree(dir);
        }
    }

    public static void testLibraryMapsLegacyNamesToPlaceholders() {
        PlaceholderLibrary library = PlaceholderLibrary.defaultLibrary();
        MappingTable table = library.applyTo(BuiltinMappings.get().copy());
        Assert.equal("dev/forgebridge/placeholders/network/simple/SimpleChannel",
                table.mapClass("net/minecraftforge/network/simple/SimpleChannel"), "removed API maps to its stub");
        Assert.notNull(table.getNotes().get("placeholder:net/minecraftforge/network/simple/SimpleChannel"),
                "mapping note records why the type is a placeholder");
    }

    public static void testDescribeListsEveryPlaceholder() {
        String description = PlaceholderLibrary.defaultLibrary().describe();
        Assert.contains(description, "ModLoadingContext -> dev/forgebridge/placeholders/fml/ModLoadingContext",
                "describe output");
        List<PlaceholderLibrary.Placeholder> all = PlaceholderLibrary.defaultLibrary().all();
        Assert.equalInt(8, all.size(), "all() returns every placeholder");
    }
}
